using CreativeFlow.Host;
using CreativeFlow.Protocol;
using System.Text.Json.Nodes;
using Microsoft.Data.Sqlite;
using Microsoft.Extensions.Primitives;
namespace CreativeFlow.Host.Tests;
public class HostManagerTests : IAsyncLifetime {
    readonly string directory=Path.Combine(Path.GetTempPath(),"creativeflow-manager-"+Guid.NewGuid().ToString("N"));
    CollaborationDatabase database=null!;HostManagerService manager=null!;WorkspaceService auth=null!;DeviceSession owner=null!;
    public async Task InitializeAsync(){database=new(directory);await database.InitializeAsync();manager=new(database);auth=new(database);var setup=await auth.SetupAsync(new("原空间","管理员"));owner=(await auth.RedeemInvitationAsync(new(setup.InvitationCode,"管理员","服务器管理员电脑")))!;}
    public Task DisposeAsync(){SqliteConnection.ClearAllPools();var absolute=Path.GetFullPath(directory);if(absolute.StartsWith(Path.GetFullPath(Path.GetTempPath()),StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(absolute).StartsWith("creativeflow-manager-"))Directory.Delete(absolute,true);return Task.CompletedTask;}
    Task<JsonObject> Run(string action,params(string,object?)[] values){var q=new JsonObject{["action"]=action};foreach(var(k,v)in values)q[k]=System.Text.Json.JsonSerializer.SerializeToNode(v);return manager.ExecuteAsync(q);}
    async Task<(string,DeviceSession)> Invite(string name){var r=await Run("invite",("name",name));var session=(await auth.RedeemInvitationAsync(new(r["code"]!.GetValue<string>(),name,"员工电脑")))!;return(session.MemberId,session);}
    [Fact] public async Task InspectDoesNotExposeTokensOrInvitationHashes(){await Invite("同事");var result=await Run("inspect");var json=result.ToJsonString();Assert.DoesNotContain(owner.Token,json);Assert.DoesNotContain("token_hash",json);Assert.DoesNotContain("code_hash",json);Assert.Equal(2,result["members"]!.AsArray().Count);}
    [Fact] public async Task ResetImmediatelyInvalidatesPreviousUnusedCode(){var r=await Run("invite",("name","新成员"));var old=r["code"]!.GetValue<string>();var reset=await Run("reinvite",("memberId",r["memberId"]!.GetValue<string>()));Assert.Null(await auth.RedeemInvitationAsync(new(old,"新成员","旧设备")));Assert.NotNull(await auth.RedeemInvitationAsync(new(reset["code"]!.GetValue<string>(),"新成员","新设备")));}
    [Fact] public async Task DisableRevokesAllDevicesAndInvitationsButEnablePreservesIdentity(){var(id,session)=await Invite("同事");var pending=await Run("reinvite",("memberId",id));await Run("disable",("memberId",id));Assert.Null(await auth.AuthenticateAsync(new StringValues("Bearer "+session.Token)));Assert.Null(await auth.RedeemInvitationAsync(new(pending["code"]!.GetValue<string>(),"同事","设备")));await Run("enable",("memberId",id));Assert.Null(await auth.AuthenticateAsync(new StringValues("Bearer "+session.Token)));var retry=await Run("reinvite",("memberId",id));var joined=await auth.RedeemInvitationAsync(new(retry["code"]!.GetValue<string>(),"同事","新电脑"));Assert.Equal(id,joined!.MemberId);}
    [Fact] public async Task OwnerCannotBeRemovedOrDisabledAndTransferRequiresJoinedMember(){await Assert.ThrowsAsync<ArgumentException>(()=>Run("disable",("memberId",owner.MemberId)));await Assert.ThrowsAsync<ArgumentException>(()=>Run("remove",("memberId",owner.MemberId)));var invitation=await Run("invite",("name","未接入"));await Assert.ThrowsAsync<ArgumentException>(()=>Run("transfer-owner",("memberId",invitation["memberId"]!.GetValue<string>())));var(id,session)=await Invite("新所有者");await Run("transfer-owner",("memberId",id));Assert.Equal("owner",(await auth.AuthenticateAsync(new StringValues("Bearer "+session.Token)))!.Role);Assert.Equal("member",(await auth.AuthenticateAsync(new StringValues("Bearer "+owner.Token)))!.Role);}
    [Fact] public async Task RenamePreservesIdentityAndDeviceRevokeIsSpecific(){var(id,session)=await Invite("旧姓名");await Run("rename-member",("memberId",id),("name","新姓名"));await Run("rename-workspace",("name","新空间"));var identity=await auth.AuthenticateAsync(new StringValues("Bearer "+session.Token));Assert.Equal("新姓名",identity!.DisplayName);Assert.Equal(id,identity.MemberId);await Run("revoke-device",("deviceId",session.DeviceId));Assert.Null(await auth.AuthenticateAsync(new StringValues("Bearer "+session.Token)));Assert.NotNull(await auth.AuthenticateAsync(new StringValues("Bearer "+owner.Token)));Assert.Equal("新空间",(await Run("inspect"))["workspace"]!["name"]!.GetValue<string>());}
    [Fact] public async Task RecoveryResetsOnlyOwnerPendingCodes(){var first=await Run("recover-owner");var member=await Run("invite",("name","同事"));var second=await Run("recover-owner");Assert.Null(await auth.RedeemInvitationAsync(new(first["code"]!.GetValue<string>(),"管理员","设备")));Assert.NotNull(await auth.RedeemInvitationAsync(new(second["code"]!.GetValue<string>(),"管理员","设备")));Assert.NotNull(await auth.RedeemInvitationAsync(new(member["code"]!.GetValue<string>(),"同事","设备")));}
    [Fact] public async Task RemoveRetainsRecordAndCancelCodePreventsJoin(){var r=await Run("invite",("name","同事"));var id=r["memberId"]!.GetValue<string>();await Run("cancel-invitations",("memberId",id));Assert.Null(await auth.RedeemInvitationAsync(new(r["code"]!.GetValue<string>(),"同事","设备")));await Run("remove",("memberId",id));var member=(await Run("inspect"))["members"]!.AsArray().Single(m=>m!["id"]!.GetValue<string>()==id)!;Assert.NotNull(member["removedAt"]);await Assert.ThrowsAsync<ArgumentException>(()=>Run("enable",("memberId",id)));}
}
